use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Exp {
    Const(i128),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression under a store.
/// If a variable is missing from the store, it evaluates to -1.
pub fn eval(e: &Exp, store: &HashMap<String, i128>) -> i128 {
    match e {
        Exp::Const(c) => *c,
        Exp::Var(name) => *store.get(name).unwrap_or(&-1),
        Exp::Plus(a, b) => eval(a, store) + eval(b, store),
        Exp::Mult(a, b) => eval(a, store) * eval(b, store),
    }
}

/// Perform a *single-step* peephole optimization at the root only.
/// Does not recurse into subexpressions.
pub fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Mult(a, b) => {
            // absorbing element: 0 * x = 0, x * 0 = 0
            if matches!(*a, Exp::Const(0)) || matches!(*b, Exp::Const(0)) {
                return Exp::Const(0);
            }
            // neutral element: 1 * x = x, x * 1 = x
            if matches!(*a, Exp::Const(1)) {
                return *b;
            }
            if matches!(*b, Exp::Const(1)) {
                return *a;
            }
            // constant folding
            if let (Exp::Const(x), Exp::Const(y)) = (&*a, &*b) {
                return Exp::Const(*x * *y);
            }
            Exp::Mult(a, b)
        }
        Exp::Plus(a, b) => {
            // neutral element: 0 + x = x, x + 0 = x
            if matches!(*a, Exp::Const(0)) {
                return *b;
            }
            if matches!(*b, Exp::Const(0)) {
                return *a;
            }
            // constant folding
            if let (Exp::Const(x), Exp::Const(y)) = (&*a, &*b) {
                return Exp::Const(*x + *y);
            }
            Exp::Plus(a, b)
        }
        other => other,
    }
}

/// Check (computationally) that the root-only optimization preserves evaluation
/// for this particular expression and store.
pub fn optimize_correct(e: Exp, s: &HashMap<String, i128>) -> bool {
    let before = eval(&e, s);
    let after = eval(&optimize(e), s);
    before == after
}